import 'r1_graph.dart';
import 'r2_graph.dart';
const String brain2MrsGraphContextVersion='B2_MRS_GRAPH_CONTEXT_V1';
class MrsGraphContext{final List<String>r1NodeIds,r2NodeIds;final List<Map<String,String>>traversal;final int depth,nodeBudget;final bool truncated;const MrsGraphContext({required this.r1NodeIds,required this.r2NodeIds,required this.traversal,required this.depth,required this.nodeBudget,required this.truncated});Map<String,Object?>toJson()=>{'format':'B2_MRS_GRAPH_CONTEXT','version':1,'contextVersion':brain2MrsGraphContextVersion,'r1NodeIds':r1NodeIds,'r2NodeIds':r2NodeIds,'traversal':traversal,'depth':depth,'nodeBudget':nodeBudget,'truncated':truncated};}
MrsGraphContext buildMrsGraphContext({required List<String> evidenceIds,required R1Graph r1,R2Graph? r2,int graphDepth=2,int nodeBudget=72,List<String> allowedEdgeTypes=const['SUPPORTS','CONTRADICTS','SUPERSEDES','DEPENDS_ON','REQUIRES','VERIFIED_BY','DERIVED_FROM','BLOCKS','AFFECTS']}){final evidence=evidenceIds.toSet();final depth=graphDepth.clamp(0,8);final budget=nodeBudget.clamp(1,256);final allowed=allowedEdgeTypes.toSet();final selected=<String>{};final queue=<MapEntry<String,int>>[];for(final node in r1.nodes.toList()..sort((a,b)=>a.id.compareTo(b.id))){if((node.sourceRecordId!=null&&evidence.contains(node.sourceRecordId))||node.evidenceIds.any(evidence.contains)){if(selected.length>=budget)break;selected.add(node.id);queue.add(MapEntry(node.id,0));}}final traversal=<Map<String,String>>[];var truncated=false;while(queue.isNotEmpty){final current=queue.removeAt(0);if(current.value>=depth)continue;final edges=r1.edges.where((e)=>allowed.contains(e.type)&&(e.from==current.key||e.to==current.key)).toList()..sort((a,b)=>a.id.compareTo(b.id));for(final e in edges){final next=e.from==current.key?e.to:e.from;traversal.add({'from':current.key,'to':next,'type':e.type});if(selected.contains(next))continue;if(selected.length>=budget){truncated=true;continue;}selected.add(next);queue.add(MapEntry(next,current.value+1));}}final r1Ids=selected.toList()..sort();final r2Ids=<String>[];if(r2!=null){final ordered=r2.nodes.toList()..sort((a,b)=>a.id.compareTo(b.id));for(final node in ordered){if(!node.derivedFrom.any(selected.contains))continue;if(r1Ids.length+r2Ids.length>=budget){truncated=true;break;}r2Ids.add(node.id);}}return MrsGraphContext(r1NodeIds:r1Ids,r2NodeIds:r2Ids,traversal:traversal,depth:depth,nodeBudget:budget,truncated:truncated);}
